#include <print>
#include <vector>

int main() {
    std::vector<int> v;
    for (int i = 1; i <= 8; ++i) {
        v.push_back(i * 10);
        std::println("放入 {} 后: 容量 {}，元素 {}", i * 10, v.capacity(), v.size());
    }
    std::println("盒子在 {}", static_cast<const void*>(v.data()));
    // 容量台阶 0 1 2 4 8，每次翻倍
    return 0;
}

